    public readonly struct GoodsQuantity:IEquatable<GoodsQuantity>{public GoodsQuantity(long value){if(value<0)throw new ArgumentOutOfRangeException(nameof(value));Value=value;}public long Value{get;}public bool Equals(GoodsQuantity other)=>Value==other.Value;public override bool Equals(object? obj)=>obj is GoodsQuantity other&&Equals(other);public override int GetHashCode()=>Value.GetHashCode();}
