    public sealed class RouteRiskInput{public RouteRiskInput(string sourceId,RouteRiskSource source){if(string.IsNullOrWhiteSpace(sourceId))throw new ArgumentException("Source ID is required.",nameof(sourceId));if(!Enum.IsDefined(typeof(RouteRiskSource),source))throw new ArgumentOutOfRangeException(nameof(source));SourceId=sourceId;Source=source;}public string SourceId{get;}public RouteRiskSource Source{get;}}
    public sealed class CaravanAccountingState
    {
        public CaravanAccountingState(long purchaseCost=0,long saleRevenue=0,long operatingCost=0,long tariffs=0,long losses=0){PurchaseCost=new MoneyAmount(purchaseCost);SaleRevenue=new MoneyAmount(saleRevenue);OperatingCost=new MoneyAmount(operatingCost);Tariffs=new MoneyAmount(tariffs);Losses=new MoneyAmount(losses);}public MoneyAmount PurchaseCost{get;private set;}public MoneyAmount SaleRevenue{get;private set;}public MoneyAmount OperatingCost{get;}public MoneyAmount Tariffs{get;}public MoneyAmount Losses{get;}public long NetResult{get{checked{return SaleRevenue.Value-PurchaseCost.Value-OperatingCost.Value-Tariffs.Value-Losses.Value;}}}public bool CanRecordPurchase(long value)=>CanAdd(PurchaseCost.Value,value);public bool CanRecordSale(long value)=>CanAdd(SaleRevenue.Value,value);public void RecordPurchase(long value){if(value<=0||!CanRecordPurchase(value))throw new InvalidOperationException("Purchase accounting is invalid.");PurchaseCost=new MoneyAmount(PurchaseCost.Value+value);}public void RecordSale(long value){if(value<=0||!CanRecordSale(value))throw new InvalidOperationException("Sale accounting is invalid.");SaleRevenue=new MoneyAmount(SaleRevenue.Value+value);}private static bool CanAdd(long current,long value){if(value<0)return false;try{checked{var unused=current+value;return unused>=0;}}catch(OverflowException){return false;}}
    }
    public sealed class CaravanCargoState
    {
        private readonly SortedDictionary<TradeGoodId,TradeGoodStock> _items=new SortedDictionary<TradeGoodId,TradeGoodStock>();public IReadOnlyCollection<TradeGoodStock> OrderedCargo=>_items.Values;public long QuantityOf(TradeGoodId id)=>_items.TryGetValue(id,out var item)?item.Quantity.Value:0;public long UsedWeight(TradeGoodRegistry goods){long total=0;checked{foreach(var x in _items.Values)total+=x.Quantity.Value*goods.GetRequired(x.GoodId).UnitWeight;}return total;}public bool CanAdd(TradeGoodId id,long quantity,long capacity,TradeGoodRegistry goods){if(quantity<=0)return false;try{checked{return UsedWeight(goods)+quantity*goods.GetRequired(id).UnitWeight<=capacity;}}catch(OverflowException){return false;}}public void Add(TradeGoodId id,long quantity,long capacity,TradeGoodRegistry goods){if(!CanAdd(id,quantity,capacity,goods))throw new InvalidOperationException("Caravan capacity would be exceeded.");if(!_items.TryGetValue(id,out var item)){item=new TradeGoodStock(id,0);_items.Add(id,item);}item.Quantity=new GoodsQuantity(checked(item.Quantity.Value+quantity));}public void Remove(TradeGoodId id,long quantity){if(quantity<=0)throw new ArgumentOutOfRangeException(nameof(quantity));if(!_items.TryGetValue(id,out var item)||item.Quantity.Value<quantity)throw new InvalidOperationException("Insufficient Caravan cargo.");item.Quantity=new GoodsQuantity(item.Quantity.Value-quantity);}
    }
    public sealed class CaravanState
    {
        private readonly List<RouteRiskInput> _riskInputs=new List<RouteRiskInput>();public CaravanState(CaravanId id,EconomicOwnerRef owner,CharacterId managerCharacterId,CityId originCityId,CityId destinationCityId,long weightCapacity,long cashBalance,TradeRepresentativeReference? representative=null,TradeRouteId? routeId=null,CaravanLifecycle lifecycle=CaravanLifecycle.Active,CaravanLocationStage locationStage=CaravanLocationStage.AtOrigin,CaravanCargoState? cargo=null,CaravanAccountingState? accounting=null,IEnumerable<RouteRiskInput>? riskInputs=null){if(!id.IsValid||!managerCharacterId.IsValid||!originCityId.IsValid||!destinationCityId.IsValid)throw new ArgumentException("Caravan references are invalid.");if(originCityId.Equals(destinationCityId))throw new ArgumentException("Caravan origin and destination must differ.");if(string.IsNullOrWhiteSpace(owner.Id)||!Enum.IsDefined(typeof(EconomicOwnerKind),owner.Kind))throw new ArgumentException("Owner is invalid.");if(weightCapacity<0)throw new ArgumentOutOfRangeException(nameof(weightCapacity));if(!Enum.IsDefined(typeof(CaravanLifecycle),lifecycle)||!Enum.IsDefined(typeof(CaravanLocationStage),locationStage))throw new ArgumentOutOfRangeException(nameof(lifecycle));Id=id;Owner=owner;ManagerCharacterId=managerCharacterId;OriginCityId=originCityId;DestinationCityId=destinationCityId;WeightCapacity=weightCapacity;CashBalance=new MoneyAmount(cashBalance);Representative=representative;RouteId=routeId;Lifecycle=lifecycle;LocationStage=locationStage;Cargo=cargo??new CaravanCargoState();Accounting=accounting??new CaravanAccountingState();if(riskInputs!=null){var seen=new HashSet<string>(StringComparer.Ordinal);foreach(var x in riskInputs){if(x==null||!seen.Add(x.Source+"\n"+x.SourceId))throw new InvalidOperationException("Duplicate route risk input.");_riskInputs.Add(x);}_riskInputs.Sort((a,b)=>{var c=a.Source.CompareTo(b.Source);return c!=0?c:StringComparer.Ordinal.Compare(a.SourceId,b.SourceId);});}}
        public CaravanId Id{get;}public EconomicOwnerRef Owner{get;}public CharacterId ManagerCharacterId{get;}public TradeRepresentativeReference? Representative{get;}public CityId OriginCityId{get;}public CityId DestinationCityId{get;}public TradeRouteId? RouteId{get;}public long WeightCapacity{get;}public MoneyAmount CashBalance{get;private set;}public CaravanLifecycle Lifecycle{get;}public CaravanLocationStage LocationStage{get;private set;}public CaravanCargoState Cargo{get;}public CaravanAccountingState Accounting{get;}public IReadOnlyList<RouteRiskInput> OrderedRiskInputs=>_riskInputs;public bool CanCredit(long amount){if(amount<0)return false;try{checked{var unused=CashBalance.Value+amount;return unused>=0;}}catch(OverflowException){return false;}}public void Credit(long amount){if(amount<=0||!CanCredit(amount))throw new InvalidOperationException("Caravan cash credit is invalid.");CashBalance=new MoneyAmount(CashBalance.Value+amount);}public void Debit(long amount){if(amount<=0||CashBalance.Value<amount)throw new InvalidOperationException("Insufficient Caravan cash.");CashBalance=new MoneyAmount(CashBalance.Value-amount);}public void MarkInTransit(){if(LocationStage!=CaravanLocationStage.AtOrigin)throw new InvalidOperationException("Caravan cannot enter transit from its current stage.");LocationStage=CaravanLocationStage.InTransit;}public void MarkAtDestination(){if(LocationStage!=CaravanLocationStage.InTransit)throw new InvalidOperationException("Caravan cannot arrive from its current stage.");LocationStage=CaravanLocationStage.AtDestination;}
    }
    public sealed class CaravanRegistry{private readonly SortedDictionary<CaravanId,CaravanState> _items=new SortedDictionary<CaravanId,CaravanState>();public IReadOnlyCollection<CaravanState> OrderedCaravans=>_items.Values;public void Add(CaravanState caravan){if(caravan==null)throw new ArgumentNullException(nameof(caravan));if(_items.ContainsKey(caravan.Id))throw new InvalidOperationException("Duplicate CaravanId.");_items.Add(caravan.Id,caravan);}public CaravanState GetRequired(CaravanId id){if(!_items.TryGetValue(id,out var item))throw new KeyNotFoundException("Caravan was not found.");return item;}}
    public sealed class EconomyState
    {
        private readonly SortedDictionary<CityId,CityMarketState> _markets=new SortedDictionary<CityId,CityMarketState>();public EconomyState(TradeGoodRegistry? goods=null,ProductionRecipeRegistry? recipes=null,CaravanRegistry? caravans=null){Goods=goods??new TradeGoodRegistry();Recipes=recipes??new ProductionRecipeRegistry();Caravans=caravans??new CaravanRegistry();}public TradeGoodRegistry Goods{get;}public ProductionRecipeRegistry Recipes{get;}public CaravanRegistry Caravans{get;}public IReadOnlyCollection<CityMarketState> OrderedMarkets=>_markets.Values;public void AddMarket(CityMarketState market){if(market==null)throw new ArgumentNullException(nameof(market));if(_markets.ContainsKey(market.CityId))throw new InvalidOperationException("Duplicate City market.");_markets.Add(market.CityId,market);}public CityMarketState GetRequiredMarket(CityId id){if(!_markets.TryGetValue(id,out var item))throw new KeyNotFoundException("City market was not found.");return item;}
